text:
.account-hub-dialog {
  display: grid;
  inline-size: 800px;
  min-block-size: 600px;
  overflow: initial;
  padding: 0;
  box-shadow: none;

  &::after {
    --hub-blur-radius: 15px;
    content: "";
    position: absolute;
    inset-block-end: -2px;
    inset-inline: calc(2 * var(--hub-blur-radius) + 5px);
    min-block-size: calc(3 * var(--hub-blur-radius));
    background: linear-gradient(to right, rgba(159, 244, 240, 1), rgba(76, 177, 249, 1), rgba(168, 85, 247, 1));
    filter: blur(var(--hub-blur-radius));
    z-index: -1;
